package com.bloodfuryreminder;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
public class BloodFuryFlashOverlay extends Overlay
{
    private final Client client;
    private int framesRemaining;

    @Inject
    public BloodFuryFlashOverlay(Client client)
    {
        this.client = client;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(PRIORITY_HIGHEST);
    }

    public void triggerFlash()
    {
        framesRemaining = 150;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Dimension dimensions = client.getRealDimensions();

        if (framesRemaining <= 0)
        {
            return null;
        }

        int frame = 150 - framesRemaining;

        // Alternate every 25 frames for a slower flash
        if ((frame / 25) % 2 == 0)
        {
            graphics.setColor(new Color(255, 0, 0, 75));
            graphics.fillRect(
                    0,
                    0,
                    dimensions.width,
                    dimensions.height
            );
        }

        framesRemaining--;

        return dimensions;
    }
}

package com.bloodfuryreminder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("com/bloodfuryreminder")
public interface BloodFuryReminderConfig extends Config
{
    @Range(min = 1, max = 100)
    @ConfigItem(
        keyName = "hpThreshold",
        name = "HP alert threshold",
        description = "Hitpoints percentage at which to show the reminder"
    )
    default int hpThreshold()
    {
        return 90;
    }

    @ConfigItem(
        keyName = "playSound",
        name = "Play alert sound",
        description = "Play a sound when the HP threshold is reached"
    )
    default boolean playSound()
    {
        return true;
    }

    @ConfigItem(
            keyName = "flashScreen",
            name = "Flash screen",
            description = "Briefly flash the screen when the HP threshold is reached"
    )
    default boolean flashScreen()
    {
        return false;
    }

    @ConfigItem(
            keyName = "showChatMessage",
            name = "Show chat message",
            description = "Show a chat message when the HP threshold is reached"
    )
    default boolean showChatMessage()
    {
        return true;
    }
}

package com.bloodfuryreminder;

import com.google.inject.Provides;
import java.awt.Toolkit;
import javax.inject.Inject;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameTick;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
        name = "Blood Fury Reminder",
        description = "Alerts when HP is high enough to conserve Blood Fury charges",
        tags = {"blood fury", "health", "hitpoints", "combat"}
)
public class BloodFuryReminderPlugin extends Plugin
{
    private static final int BLOOD_FURY_ID = 24780;

    @Inject
    private Client client;

    @Inject
    private BloodFuryReminderConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BloodFuryFlashOverlay flashOverlay;

    private boolean alreadyAlerted;
    private boolean initialHpChecked;

    @Override
    protected void startUp()
    {
        overlayManager.add(flashOverlay);
        alreadyAlerted = false;
        initialHpChecked = false;
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(flashOverlay);
        alreadyAlerted = false;
        initialHpChecked = false;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            resetReminder();
            return;
        }

        // Never monitor HP unless the Blood Fury is equipped.
        if (!isBloodFuryEquipped())
        {
            resetReminder();
            return;
        }

        int currentHp = client.getBoostedSkillLevel(Skill.HITPOINTS);
        int maximumHp = client.getRealSkillLevel(Skill.HITPOINTS);

        if (maximumHp <= 0)
        {
            return;
        }

        int hpPercentage = (currentHp * 100) / maximumHp;

        // First check after equipping: don't alert immediately.
        if (!initialHpChecked)
        {
            alreadyAlerted = hpPercentage >= config.hpThreshold();
            initialHpChecked = true;
            return;
        }

        if (hpPercentage >= config.hpThreshold())
        {
            if (!alreadyAlerted)
            {
                alertPlayer(hpPercentage);
                alreadyAlerted = true;
            }
        }
        else
        {
            alreadyAlerted = false;
        }
    }

    private void resetReminder()
    {
        alreadyAlerted = false;
        initialHpChecked = false;
    }

    private boolean isBloodFuryEquipped()
    {
        ItemContainer equipment =
                client.getItemContainer(InventoryID.EQUIPMENT);

        if (equipment == null)
        {
            return false;
        }

        Item amulet = equipment.getItem(
                EquipmentInventorySlot.AMULET.getSlotIdx()
        );

        return amulet != null && amulet.getId() == BLOOD_FURY_ID;
    }

    private void alertPlayer(int hp)
    {
        if (config.showChatMessage())
        {
            client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "[Blood Fury Reminder] HP is " + hp
                            + "%! Consider switching off your Blood Fury.",
                    null
            );
        }

        if (config.flashScreen())
        {
            flashOverlay.triggerFlash();
        }

        if (config.playSound())
        {
            Toolkit.getDefaultToolkit().beep();
        }
    }

    @Provides
    BloodFuryReminderConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BloodFuryReminderConfig.class);
    }
}

package com.bloodfuryreminder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BloodFuryReminderLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BloodFuryReminderPlugin.class);
		RuneLite.main(args);
	}
}

